create table if not exists public.ce_production_certifications(id uuid primary key default gen_random_uuid(),certified boolean not null,failed_checks jsonb not null default '[]'::jsonb,evidence jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());alter table public.ce_production_certifications enable row level security;revoke all on public.ce_production_certifications from public,anon,authenticated;grant select,insert,update,delete on public.ce_production_certifications to service_role;